;;
; @file   script_08.asm
; @brief  Building NPC schedule variant for the days on which strcDialogDisplay.mapFlags has bit $0200 set (a special-day
;         flag; meaning not named in the sources; docs/regions-ai.md lists the earthquake aftermath scenes of this group).
;         Slots 0-7 mirror script_01 for the mayor's house, church, flower shop, tool shop, restaurant, fortune teller,
;         animal shop and carpenter's house. Confidence: medium (derived from the dialogs, flags and callers).
; @bank   $B3   (AI byte code; script id $08, slot table generated by tools/ai/aidata.py from defs/ai/scripts.json)
; @see    script_01 script_04 script_06 script_07 docs/ai/commands.md
;;



    incsrc "../../../../build/gen/ai/slots_08.asm"
 
; Slot 0: NPC schedule of the major house while mapFlags bit $0200 is set.
; Entry code: starts 2 child scripts (slots $01, $02).
; Slot index: 0
; Started by: fAreaEvents_MajorHouseHandler (A=$0000)
pAIScripting0x08_MajorHouse:
 
    %AICMD0x11_EnableUserControl()                             ;B3E0DF
    %AICMD0x09_StartScript($01, pAIScripting0x08_MajorHouse_Actor01)                                   ;B3E0E0
    %AICMD0x12_Jump(pAIScripting0x08_L002)                                   ;B3E0E4
; Idle loop: wait, then repeat.
pAIScripting0x08_MajorHouse_Idle:
    %AICMD0x13_Wait(1)                                         ;B3E0E7
    %AICMD0x12_Jump(pAIScripting0x08_MajorHouse_Idle)                                   ;B3E0EA
pAIScripting0x08_L002:
    %AICMD0x14_JumpIfFlagSet(strcFlags.event2, $00, pAIScripting0x08_L003)   ;B3E0ED
    %AICMD0x14_JumpIfFlagSet(strcFlags.event4, $0C, pAIScripting0x08_L003)   ;B3E0F4
    %AICMD0x09_StartScript($02, pAIScripting0x08_MajorHouse_Actor02_Maria)                                   ;B3E0FB
pAIScripting0x08_L003:
    %AICMD0x12_Jump(pAIScripting0x08_MajorHouse_Idle)                                   ;B3E0FF
; Child script (slot $01) of MajorHouse: actor. Spawns at (392,160). Waits for the player to press A. Dialogs $0200, $03B9,
; $0401.
pAIScripting0x08_MajorHouse_Actor01:
    %AICMD0x1A_SpawnNpc($0188, $00A0, aAIScriptingData_L063, $00)                     ;B3E102
; Idle until the player presses A at the NPC (AICMD0x2D): jumps to OnInteract, or to OnItemOffered while an item is carried.
pAIScripting0x08_MajorHouse_Actor01_WaitInteract:
    %AICMD0x2D_JumpOnInteract(pAIScripting0x08_MajorHouse_Actor01_OnInteract, pAIScripting0x08_MajorHouse_Actor01_OnItemOffered)                               ;B3E10A
    %AICMD0x12_Jump(pAIScripting0x08_MajorHouse_Actor01_WaitInteract)                                   ;B3E10F
; Handler for A pressed while carrying an item.
pAIScripting0x08_MajorHouse_Actor01_OnItemOffered:
    %AICMD0x16_JumpIfBetween8(wram80(strcPlayerData.carryItemIdPrev), 9, 12, pAIScripting0x08_MajorHouse_Actor01_Say_03B9)         ;B3E112
    %AICMD0x1C_ShowDialog($0200, $00)                          ;B3E11A
    %AICMD0x12_Jump(pAIScripting0x08_MajorHouse_Actor01_WaitInteract)                                   ;B3E11E
; Shows dialog $03B9.
pAIScripting0x08_MajorHouse_Actor01_Say_03B9:
    %AICMD0x1C_ShowDialog($03B9, $00)                          ;B3E121
    %AICMD0x12_Jump(pAIScripting0x08_MajorHouse_Actor01_WaitInteract)                                   ;B3E125
; Handler for A pressed with empty hands.
pAIScripting0x08_MajorHouse_Actor01_OnInteract:
    %AICMD0x1C_ShowDialog($0401, $00)                          ;B3E128
    %AICMD0x12_Jump(pAIScripting0x08_MajorHouse_Actor01_WaitInteract)                                   ;B3E12C
; Child script (slot $02) of MajorHouse: actor. Spawns at (72,408). Waits for the player to press A. Dialogs $043D, $0174,
; $016B, $0200, $0212, $03B5 ....
pAIScripting0x08_MajorHouse_Actor02_Maria:
