pAIScripting0x08_MajorHouse_Actor02_Maria_OnItemOffered:
    %AICMD0x16_JumpIfBetween8(wram80(strcPlayerData.carryItemIdPrev), 1, 5, pAIScripting0x08_MajorHouse_Actor02_Maria_Say_03B2)          ;B3E161
    %AICMD0x16_JumpIfBetween8(wram80(strcPlayerData.carryItemIdPrev), 16, 23, pAIScripting0x08_MajorHouse_Actor02_Maria_Say_03B2)        ;B3E169
    %AICMD0x15_JumpIfEquals8(wram80(strcPlayerData.carryItemIdPrev), 6, pAIScripting0x08_MajorHouse_Actor02_Maria_Say_03B5)              ;B3E171
    %AICMD0x15_JumpIfEquals8(wram80(strcPlayerData.carryItemIdPrev), 25, pAIScripting0x08_MajorHouse_Actor02_Maria_Say_0212)             ;B3E178
    %AICMD0x15_JumpIfEquals8(wram80(strcPlayerData.carryItemIdPrev), 73, pAIScripting0x08_MajorHouse_Actor02_Maria_Say_0212)             ;B3E17F
    %AICMD0x16_JumpIfBetween8(wram80(strcPlayerData.carryItemIdPrev), 9, 12, pAIScripting0x08_MajorHouse_Actor02_Maria_Say_01DA)         ;B3E186
    %AICMD0x1C_ShowDialog($0200, $00)                          ;B3E18E
